#include <iomanip>
#include <iostream>
#include <vector>

const double kLossLimit = 50.0;  // the desk's limit, at namespace scope

double buggyPnl(std::vector<double> fills) {
    double pnl = 0.0;
    for (double fill : fills) {
        double pnl = 0.0;  // shadows the outer pnl
        pnl += fill;
    }
    return pnl;  // the outer pnl, never touched
}

double fixedPnl(std::vector<double> fills) {
    double pnl = 0.0;
    for (double fill : fills) {
        pnl += fill;  // no type, so this is the outer pnl
    }
    return pnl;
}

int main() {
    const std::vector<double> fills = {12.50, -4.00, 7.25, -1.75};
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "buggy pnl: " << buggyPnl(fills) << '\n';
    std::cout << "fixed pnl: " << fixedPnl(fills) << '\n';

    const double kLossLimit = 20.0;  // this trader's limit hides the desk's
    std::cout << "trader limit: " << kLossLimit << '\n';
    std::cout << "desk limit: " << ::kLossLimit << '\n';
    return 0;
}

