    using std::cout;
    cout << std::fixed << std::setprecision(4);
    {
        using v1::fee;
        cout << "v1 fee: " << fee(10'000.0) << '\n';
    }
    {
        using v2::fee;
        cout << "v2 fee: " << fee(10'000.0) << '\n';
    }
    cout << "small order: " << v1::fee(500.0) << " vs " << v2::fee(500.0) << '\n';
    return 0;
}

