#include <iostream>
#include <string>
#include <utility>

namespace ids {
    std::string mic(int id) {
        return "ID" + std::to_string(id);
    }
}

namespace venue {
    enum class Code { Nyse, Nasdaq, Cme };

    std::string mic(Code c) {
        switch (c) {
            case Code::Nyse: return "XNYS";
            case Code::Nasdaq: return "XNAS";
            case Code::Cme: return "XCME";
        }
        return "?";
    }
}

int main() {
    std::cout << mic(venue::Code::Nasdaq) << '\n';
    using ids::mic;
    std::cout << mic(7) << '\n';
    std::cout << mic(venue::Code::Cme) << '\n';

    venue::Code primary = venue::Code::Nyse, backup = venue::Code::Cme;
    std::string first = "ARCX", second = "BATS";
    using std::swap;
    swap(primary, backup);
    swap(first, second);
    std::cout << static_cast<int>(primary) << ' ' << static_cast<int>(backup) << ' ' << first << ' ' << second << '\n';
    return 0;
}
